import React, { forwardRef, useEffect } from 'react';
import styled from 'styled-components';

import { PanelContext } from './contexts/PanelContext.js';
import { PageDrawer } from './DetailView.js';
import { _useConditionalPagePanel } from './hooks/_useConditionalPagePanel.js';
import { _usePageContext } from './hooks/_usePageContext.js';
import {
  PREFERRED_WIDTHS,
  PANEL_ORDER,
  MIN_WIDTHS,
  BREAKPOINTS,
} from './Page.js';
import { Panel } from './Panel/Panel.js';
import type { PanelProps } from './Panel/Panel.js';
import { Resizer } from './Panel/Resizer.js';
import type { PanelSize } from './Panel/types/shared-panel-types.js';
import type {
  PagePanelSizes,
  PagePanelProps,
} from './types/shared-page-types.js';
import { useBreakpoint } from '../../core/hooks/useBreakpoint.js';
import type { DataTestId } from '../../core/types/data-props.js';
import type { StylingProps } from '../../core/types/styling-props.js';
import type { WithChildren } from '../../core/types/with-children.js';

//#region Styled Components
const StyledSidebar = /* @__PURE__ */ styled(Panel)<PanelProps>({
  boxSizing: 'border-box',
  height: '100%',
});
StyledSidebar.displayName = 'Page.Sidebar';
//#endregion

//#region Props
export interface SidebarOwnProps
  extends WithChildren,
    Omit<React.HTMLAttributes<HTMLDivElement>, 'onResize' | keyof StylingProps>,
    StylingProps,
    DataTestId {
  /**
   * The desired width of the sidebar.
   * Depending on the available screen width and other panel configurations,
   * the size of the panel might not match the `preferredWidth` exactly.
   * @defaultValue 15%
   */
  preferredWidth?: PanelSize;
  /**
   * The minimum width of the sidebar in pixels.
   * @defaultValue 200
   */
  minWidth?: number;
  /**
   * Screen size below which the overlay Drawer will be shown.
   * @defaultValue 640
   */
  breakpoint?: number;
  /**
   * If the sidebar's width can be resized (by drag and drop)
   * @defaultValue true
   */
  resizable?: boolean;
  /**
   * Defines if the Sidebar content will be kept in the DOM, even if the content
   * is not shown to the user.
   * @defaultValue false
   */
  keepMounted?: boolean;
  /**
   * Callback triggered after resizing is finished with the new panel sizes of
   * all existing panels and the newly applied panel width (in px).
   */
  onResize?: (sizes: PagePanelSizes, width: number) => void;
  /**
   * Notifies the user if an action happened that should change the dismissed state
   * like clicking on the backdrop on mobile.
   * The returned state is only a recommendation and might differ from what the actual
   * state of the panel should be.
   */
  onDismissChange?: (state: boolean, reason: string) => void;
}

export type SidebarProps = SidebarOwnProps & PagePanelProps;
//#endregion

/** The `Sidebar` component is used inside the `Page` component for displaying content in the corresponding panel. */
export const Sidebar = forwardRef<HTMLDivElement, SidebarProps>(
  (props, forwardedRef) => {
    const {
      children,
      dismissed,
      defaultDismissed,
      onDismissChange,
      resizable = true,
      breakpoint = BREAKPOINTS.sidebar,
      onResize,
      preferredWidth = PREFERRED_WIDTHS.sidebar,
      minWidth = MIN_WIDTHS.sidebar,
      className: consumerClassName,
      style: consumerStyle,
      'data-testid': dataTestId,
      keepMounted = false,
      ...remainingProps
    }: SidebarProps = props;

    const showPanel = useBreakpoint(`(min-width: ${breakpoint}px)`, true);
    const isControlled = dismissed !== undefined;

    // Register the panel with the page and set its initial state.
    _useConditionalPagePanel({
      name: 'sidebar',
      defaultDismissed,
      dismissed,
      showPanel,
      breakpoint,
    });
    const { sidebarDismissed, setPanelDismissed } = _usePageContext();

    useEffect(() => {
      const reason = showPanel ? 'above breakpoint' : 'below breakpoint';
      onDismissChange?.(!showPanel, reason);
      // Excluding onDismissChange to trigger the effect only if the screen size reaches the breakpoint.
      // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [showPanel]);

    // The drawer handles the dismissing on its own, to ensure the proper animation, therefore, the check excludes the mobile view.
    // If the panel is controlled, we check the dismissed prop directly to make sure the panel is instantly added to state when
    // mounting. Since the default state of the panel in the context is set to 'dismissed', the layout effect in the parent panel would
    // else be triggered twice. Initially, only with the 'main' panel, and then again to add the 'sidebar'.
    if (
      ((isControlled && dismissed) || (!isControlled && sidebarDismissed)) &&
      showPanel
    ) {
      if (keepMounted === true) {
        return <div style={{ display: 'none' }}>{children}</div>;
      }
      return null;
    }

    return (
      <PanelContext.Provider value={{ panelName: 'sidebar' }}>
        {showPanel ? (
          <>
            <StyledSidebar
              // Spreading remaining props for now to allow custom styles.
              // This will be improved as soon as our guidelines for custom styles are rolled out.
              {...remainingProps}
              onResize={(sizes, width: number) => {
                onResize?.(sizes as PagePanelSizes, width);
              }}
              ref={forwardedRef}
              name="sidebar"
              order={PANEL_ORDER.sidebar}
              preferredWidth={preferredWidth}
              minWidth={minWidth}
              resizable={resizable}
              dismissible="left"
              className={consumerClassName}
              style={consumerStyle}
              data-testid={dataTestId}
            >
              {children}
            </StyledSidebar>
            <Resizer
              data-testid="page-sidebar-resize-handle"
              order={PANEL_ORDER.sidebar}
              resizable={resizable}
              name="sidebar-resize-handle"
            />
          </>
        ) : (
          <PageDrawer
            placement="left"
            width="wide"
            isDismissed={sidebarDismissed}
            onDismiss={(state, reason) => {
              // Close panel if it is uncontrolled and the user clicks on the backdrop.
              if (
                dismissed === undefined &&
                state === true &&
                (reason === 'backdrop' || reason === 'escape')
              ) {
                setPanelDismissed('sidebar', true);
              }
              onDismissChange?.(state, reason);
            }}
            className={consumerClassName}
            style={consumerStyle}
            data-testid={dataTestId}
            {...remainingProps}
          >
            {children}
          </PageDrawer>
        )}
      </PanelContext.Provider>
    );
  },
);

(Sidebar as typeof Sidebar & { displayName: string }).displayName =
  'Page.Sidebar';
